import { useEffect, useState } from 'react';

import { findTimeZone } from '@protontech/timezone-support';

import { getSilentApi } from '@proton/shared/lib/api/helpers/customConfig';
import { getLocation } from '@proton/shared/lib/api/vpn';
import { singleCountryTimezoneDatabase } from '@proton/shared/lib/date/singleCountryTimezoneDatabase';
import { manualFindTimeZone } from '@proton/shared/lib/date/timezoneDatabase';
import { getNaiveCountryCode } from '@proton/shared/lib/i18n/helper';
import type { Api, MyLocationResponse } from '@proton/shared/lib/interfaces';

import useApi from './useApi';

const tryTimezone = (tz: string): string | undefined =>
    singleCountryTimezoneDatabase[tz as keyof typeof singleCountryTimezoneDatabase];

const getCountryFromTimezone = () => {
    try {
        const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

        if (timezone) {
            return tryTimezone(timezone) || tryTimezone(manualFindTimeZone(timezone) || findTimeZone(timezone).name);
        }
    } catch (e) {
        // undefined
    }
};

export const getCountryFromLanguage = () => {
    const language = navigator.languages.find((language) => /[_-]/.test(language));
    if (language) {
        return getNaiveCountryCode(language);
    }
};

const getStaticState = () => {
    return (getCountryFromTimezone() || getCountryFromLanguage())?.toUpperCase();
};

const getMyCountry = async (api: Api): Promise<string | undefined> => {
    // TODO: Have a non-VPN dedicated API for that purpose
    const value = await api<MyLocationResponse>(getLocation());
    return value?.Country?.toUpperCase();
};

const state: { initialized: boolean; promise: null | Promise<string | undefined>; value: string | undefined } = {
    promise: null,
    value: undefined,
    initialized: false,
};

const getInitialValue = () => {
    if (!state.initialized) {
        state.initialized = true;
        state.value = getStaticState();
    }
    return state.value;
};

const getCountryPromise = (api: Api) => {
    if (state.promise) {
        return state.promise;
    }
    state.promise = getMyCountry(getSilentApi(api))
        .then((value) => {
            state.value = value;
            return value;
        })
        .catch(() => {
            return undefined;
        });
    return state.promise;
};

const useMyCountry = (): [string | undefined, boolean] => {
    const [country, setMyCountry] = useState<string | undefined>(getInitialValue);
    const api = useApi();
    useEffect(() => {
        if (country) {
            return;
        }
        void getCountryPromise(api).then(setMyCountry);
    }, []);
    return [country, !country];
};

export default useMyCountry;

import { useHistory } from 'react-router-dom';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import { useMyCountry, useSecurityCheckup, useUserSettings } from '@proton/components';
import RecoveryPhone from '@proton/components/containers/recovery/phone/RecoveryPhone';
import { SECURITY_CHECKUP_PATHS } from '@proton/shared/lib/constants';

import AccountLoaderPage from '../../../../content/AccountLoaderPage';
import SecurityCheckupMain from '../../components/SecurityCheckupMain';
import SecurityCheckupMainIcon from '../../components/SecurityCheckupMainIcon';
import SecurityCheckupMainTitle from '../../components/SecurityCheckupMainTitle';
import { phoneIcon } from '../../methodIcons';

const SetPhoneContainer = () => {
    const history = useHistory();

    const { securityState } = useSecurityCheckup();
    const { phone } = securityState;

    const [userSettings, loadingUserSettings] = useUserSettings();
    const [defaultCountry, loadingCountry] = useMyCountry();

    if (loadingUserSettings || loadingCountry) {
        return <AccountLoaderPage />;
    }

    return (
        <SecurityCheckupMain>
            <SecurityCheckupMainTitle prefix={<SecurityCheckupMainIcon icon={phoneIcon} color="danger" />}>
                {c('Safety review').t`Add a recovery phone number`}
            </SecurityCheckupMainTitle>

            <div className="mb-4">
                {c('Safety review')
                    .t`You can use your recovery phone to regain access to your account if you forget your password.`}
            </div>

            <RecoveryPhone
                autoFocus
                persistPasswordScope
                defaultCountry={defaultCountry}
                phone={userSettings.Phone}
                hasReset={!!userSettings.Phone.Reset}
                disableVerifyCta
                inputProps={{ label: c('Safety review').t`Recovery phone number` }}
                renderForm={({ onSubmit, input, submitButtonProps }) => {
                    return (
                        <form onSubmit={onSubmit}>
                            <div>{input}</div>

                            <Button className="mt-4" fullWidth color="norm" {...submitButtonProps}>
                                {c('Action').t`Add phone number`}
                            </Button>
                        </form>
                    );
                }}
                onSuccess={() => {
                    if (phone.verified) {
                        history.push(SECURITY_CHECKUP_PATHS.ROOT);
                        return;
                    }

                    history.push(`${SECURITY_CHECKUP_PATHS.VERIFY_PHONE}?setup=1`);
                }}
            />
        </SecurityCheckupMain>
    );
};

export default SetPhoneContainer;

import { useState } from 'react';
import { useHistory } from 'react-router-dom';

import { c } from 'ttag';

import { Button } from '@proton/atoms';
import {
    InputFieldTwo,
    PhoneInput,
    Tabs,
    startUnAuthFlow,
    useApi,
    useErrorHandler,
    useFormErrors,
    useMyCountry,
    useNotifications,
} from '@proton/components';
import { useLoading } from '@proton/hooks';
import { requestUsername } from '@proton/shared/lib/api/reset';
import type { APP_NAMES } from '@proton/shared/lib/constants';
import { requiredValidator } from '@proton/shared/lib/helpers/formValidators';
import noop from '@proton/utils/noop';

import { useFlowRef } from '../useFlowRef';
import type { MetaTags } from '../useMetaTags';
import { useMetaTags } from '../useMetaTags';
import Content from './Content';
import Header from './Header';
import Layout from './Layout';
import Main from './Main';
import PublicHelpLink from './PublicHelpLink';

type Method = 'email' | 'phone';
const ForgotUsernameForm = ({
    onSubmit,
    onChangeMethod,
    method,
    defaultCountry,
    loginUrl,
}: {
    onSubmit: (data: { email: string; method: 'email' } | { phone: string; method: 'phone' }) => Promise<void>;
    onChangeMethod: (method: Method) => void;
    method: Method;
    defaultCountry?: string;
    loginUrl: string;
}) => {
    const history = useHistory();
    const [loading, withLoading] = useLoading();
    const [email, setEmail] = useState('');
    const [phone, setPhone] = useState('');

    const { validator, onFormSubmit } = useFormErrors();

    return (
        <form
            name="forgot-username"
            onSubmit={(e) => {
                e.preventDefault();
                if (loading || !onFormSubmit()) {
                    return;
                }
                withLoading(onSubmit(method === 'email' ? { email, method } : { phone, method })).catch(noop);
            }}
            method="post"
        >
            <Tabs
                fullWidth
                tabs={[
                    {
                        title: c('Title').t`Email`,
                        content: (
                            <>
                                <div className="mb-4 color-weak">
                                    {c('Info')
                                        .t`Enter your recovery email address and we will send you your username or email address.`}
                                </div>
                                <InputFieldTwo
                                    id="email"
                                    bigger
                                    label={c('Label').t`Recovery email address`}
                                    error={validator(method === 'email' ? [requiredValidator(email)] : [])}
                                    autoFocus
                                    disableChange={loading}
                                    autoComplete="email"
                                    value={email}
                                    onValue={setEmail}
                                />
                            </>
                        ),
                    },
                    {
                        title: c('Title').t`Phone`,
                        content: (
                            <>
                                <div className="mb-4 color-weak">
                                    {c('Info')
                                        .t`Enter your recovery phone number and we will send you your username or email address.`}
                                </div>
                                <InputFieldTwo
                                    as={PhoneInput}
                                    id="phone"
                                    bigger
                                    label={c('Label').t`Recovery phone number`}
                                    error={validator(method === 'phone' ? [requiredValidator(phone)] : [])}
                                    autoFocus
                                    defaultCountry={defaultCountry}
                                    disableChange={loading}
                                    autoComplete="phone"
                                    value={phone}
                                    onChange={setPhone}
                                />
                            </>
                        ),
                    },
                ]}
                value={method === 'email' ? 0 : 1}
                onChange={(id) => onChangeMethod(id === 0 ? 'email' : 'phone')}
            />
            <Button size="large" color="norm" type="submit" fullWidth loading={loading} className="mt-6">
                {c('Action').t`Send my username`}
            </Button>
            <Button
                size="large"
                color="norm"
                shape="ghost"
                fullWidth
                className="mt-2"
                onClick={() => history.push(loginUrl)}
            >{c('Action').t`Return to sign in`}</Button>
        </form>
    );
};

interface Props {
    onBack?: () => void;
    loginUrl: string;
    metaTags: MetaTags;
    toApp?: APP_NAMES;
}

const ForgotUsernameContainer = ({ toApp, metaTags, onBack, loginUrl }: Props) => {
    useMetaTags(metaTags);
    const history = useHistory();
    const normalApi = useApi();
    const silentApi = <T,>(config: any) => normalApi<T>({ ...config, silence: true });
    const { createNotification } = useNotifications();
    const errorHandler = useErrorHandler();
    const [method, setMethod] = useState<Method>('email');
    const [defaultCountry] = useMyCountry();

    const createFlow = useFlowRef();

    const handleBackStep = (() => {
        return (
            onBack ||
            (() => {
                history.push(loginUrl);
            })
        );
    })();

    const children = (
        <Main>
            <Header title={c('Title').t`Find email or username`} onBack={handleBackStep} />
            <Content>
                <ForgotUsernameForm
                    loginUrl={loginUrl}
                    method={method}
                    onChangeMethod={setMethod}
                    defaultCountry={defaultCountry}
                    onSubmit={async (data) => {
                        try {
                            const validateFlow = createFlow();
                            await startUnAuthFlow();
                            const config = data.method === 'email' ? { Email: data.email } : { Phone: data.phone };
                            await silentApi(requestUsername(config));
                            if (validateFlow()) {
                                const text =
                                    data.method === 'email'
                                        ? c('Success')
                                              .t`You will receive your username via email within a minute if you entered a valid recovery email address.`
                                        : c('Success')
                                              .t`You will receive your username via SMS within a minute if you entered a valid recovery phone number.`;
                                createNotification({ text });
                                history.push(loginUrl);
                            }
                        } catch (e: any) {
                            errorHandler(e);
                        }
                    }}
                />
            </Content>
        </Main>
    );
    return (
        <Layout onBack={handleBackStep} bottomRight={<PublicHelpLink />} hasDecoration={true} toApp={toApp}>
            {children}
        </Layout>
    );
};

export default ForgotUsernameContainer;

import type { Ref } from 'react';
import { forwardRef, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';

import type { InputProps } from '@proton/atoms';
import { Input } from '@proton/atoms';
import { useRightToLeft } from '@proton/components/containers/rightToLeft/useRightToLeft';
import useCombinedRefs from '@proton/hooks/useCombinedRefs';
import clsx from '@proton/utils/clsx';

import PhoneCountrySelect from './PhoneCountrySelect';
import {
    getCountries,
    getCountryFromNumber,
    getCursorPosition,
    getExamplePlaceholder,
    getFormattedValue,
    getNumberWithCountryCode,
    getNumberWithoutCountryCode,
    getSafeCountryCallingCode,
    getSpecificCountry,
    getSpecificMaxLength,
    getTrimmedString,
} from './helper';

const usePreviousValue = <T,>(value: T) => {
    const ref = useRef<T>();
    useEffect(() => {
        ref.current = value;
    }, [value]);
    return ref.current;
};

export interface Props extends Omit<InputProps, 'type' | 'value' | 'onChange'> {
    value: string;
    defaultCountry?: string;
    embedded?: boolean;
    onChange: (value: string) => void;
}

const PhoneInputBase = (
    { value: actualValue = '', defaultCountry = 'US', embedded, onChange, onValue, ...rest }: Props,
    ref: Ref<HTMLInputElement>
) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const selectionRef = useRef<number | null>(null);
    const oldSpecificCountryLengthRef = useRef<number>(0);
    const [isCountryCallingCodeMode, setIsCountryCallingCodeMode] = useState(false);
    const [oldCountry, setOldCountry] = useState(defaultCountry);

    const trimmedValue = getTrimmedString(actualValue);
    const previousTrimmedValue = usePreviousValue(trimmedValue);

    const oldCountryCallingCode = getSafeCountryCallingCode(oldCountry);
    const valueWithCountryCallingCode = getNumberWithCountryCode(trimmedValue, oldCountryCallingCode);

    const countryCodeFromValue = getCountryFromNumber(valueWithCountryCallingCode);
    const countryCallingCodeFromValue = getSafeCountryCallingCode(countryCodeFromValue);
    const valueWithoutCountryCallingCode = getNumberWithoutCountryCode(
        valueWithCountryCallingCode,
        countryCallingCodeFromValue
    );
    const [valueCountryCodeSpecific, foundLength] = getSpecificCountry(
        valueWithoutCountryCallingCode,
        countryCallingCodeFromValue,
        oldCountryCallingCode === countryCallingCodeFromValue &&
            valueWithoutCountryCallingCode.length < oldSpecificCountryLengthRef.current
            ? oldCountry
            : countryCodeFromValue
    );

    const placeholder = getNumberWithoutCountryCode(
        getExamplePlaceholder(valueCountryCodeSpecific),
        countryCallingCodeFromValue
    );

    const formattedValue = getFormattedValue(valueWithCountryCallingCode).trim();
    const formattedValueInMode = isCountryCallingCodeMode
        ? formattedValue
        : getNumberWithoutCountryCode(formattedValue, countryCallingCodeFromValue);

    const countryCode = (() => {
        // 1. Going from '' -> '+' === remove country
        const isNullToPlus = previousTrimmedValue === '' && trimmedValue === '+';
        if (isNullToPlus) {
            return '';
        }
        // 2. No country and going from '+' -> '' === add back default country
        const isEmptyCountryToNull = previousTrimmedValue === '+' && trimmedValue === '' && oldCountry === '';
        if (isEmptyCountryToNull) {
            return defaultCountry;
        }
        // 3. Guess country from number
        return valueCountryCodeSpecific || oldCountry;
    })();

    useLayoutEffect(() => {
        if (trimmedValue === '+') {
            setOldCountry('');
            return;
        }
        // Setting from country select
        if (trimmedValue !== '') {
            oldSpecificCountryLengthRef.current = foundLength;
        }
        setOldCountry(countryCode);
    }, [countryCode]);

    useLayoutEffect(() => {
        const inputEl = inputRef.current;
        const selection = selectionRef.current;
        if (!inputEl || selection === null) {
            return;
        }
        const i = getCursorPosition(selection, formattedValueInMode);
        inputEl.selectionStart = i;
        inputEl.selectionEnd = i;
        selectionRef.current = null;
    });

    const countries = useMemo(() => getCountries(), []);
    const selectedValue = countries.find((data) => data.countryCode === countryCode);
    const [isRTL] = useRightToLeft();

    // we force dir="ltr" in all cases, because otherwise phone number will be displayed
    // in reverse in RTL languages, which is not recommended
    return (
        <Input
            {...rest}
            type="tel"
            value={formattedValueInMode}
            ref={useCombinedRefs(inputRef, ref)}
            placeholder={placeholder}
            dir="ltr"
            containerProps={{ dir: 'ltr' }}
            className={clsx([isRTL ? 'text-right' : null])}
            prefix={
                <PhoneCountrySelect
                    embedded={embedded}
                    value={selectedValue}
                    options={countries}
                    onChange={(newSelectedValue) => {
                        oldSpecificCountryLengthRef.current = getSpecificMaxLength(
                            getSafeCountryCallingCode(newSelectedValue.countryCode),
                            newSelectedValue.countryCode
                        );
                        setIsCountryCallingCodeMode(false);
                        setOldCountry(newSelectedValue.countryCode);
                        onChange('');
                    }}
                    onClosed={(isFromSelection) => {
                        if (isFromSelection) {
                            inputRef.current?.focus();
                        }
                    }}
                />
            }
            onChange={(event) => {
                const {
                    target,
                    target: { value: newStringValue },
                } = event;
                selectionRef.current = getTrimmedString(newStringValue.slice(0, target.selectionEnd || 0)).length;
                const newTrimmedValue = getTrimmedString(newStringValue);
                setIsCountryCallingCodeMode(newTrimmedValue[0] === '+');
                const newValue = !newTrimmedValue.length
                    ? ''
                    : getNumberWithCountryCode(newTrimmedValue, countryCallingCodeFromValue);
                onChange(newValue);
            }}
        />
    );
};

const PhoneInput = forwardRef<HTMLInputElement, Props>(PhoneInputBase);
export default PhoneInput;

import { memo, useState } from 'react';

import { c } from 'ttag';

import { useAddresses } from '@proton/account/addresses/hooks';
import { Button, ButtonLike, type ButtonLikeSize } from '@proton/atoms';
import {
    Icon,
    Tooltip,
    useActiveBreakpoint,
    useModalStateObject,
    useMyCountry,
    useNotifications,
} from '@proton/components';
import { TelemetryMailOnboardingEvents } from '@proton/shared/lib/api/telemetry';
import { BRAND_NAME, MAIL_APP_NAME } from '@proton/shared/lib/constants';
import { textToClipboard } from '@proton/shared/lib/helpers/browser';
import { CHECKLIST_DISPLAY_TYPE } from '@proton/shared/lib/interfaces';
import { sortAddresses } from '@proton/shared/lib/mail/addresses';
import clsx from '@proton/utils/clsx';

import { useMailOnboardingTelemetry } from 'proton-mail/components/onboarding/useMailOnboardingTelemetry';
import { useGetStartedChecklist } from 'proton-mail/containers/onboardingChecklist/provider/GetStartedChecklistProvider';

import { ONLINE_SERVICES, type OnlineServicesKey } from '../../../constants';
import UpdateMailAddressModal from './UpdateMailAddressModal';

type Category = 'finance' | 'social-media' | 'shopping';

interface TabProps {
    categories: { id: Category; name: string }[];
    className?: string;
    onClick: (clickedCategory: Category) => void;
    selectedID: string;
    size: ButtonLikeSize;
}

const Pills = ({ categories, onClick, selectedID, className, size }: TabProps) => (
    <div className="inline-flex gap-0.5 sm:gap-1 md:gap-4 flex-row">
        {categories.map(({ name, id }) => (
            <Button
                className={clsx([selectedID === id && 'button-solid-norm-light', className])}
                color={selectedID === id ? 'norm' : 'weak'}
                shape={selectedID === id ? 'solid' : 'ghost'}
                key={id}
                pill
                onClick={() => onClick(id)}
                size={size}
            >
                {name}
            </Button>
        ))}
    </div>
);

const getFinanceServicesByCountry = ({
    category,
    countryLocation,
}: {
    category: 'finance' | 'social-media' | 'shopping';
    countryLocation: string | undefined;
}) => {
    if (category === 'finance') {
        if (countryLocation === 'GB') {
            return ['hsbc', 'barclays', 'lloyds'] satisfies OnlineServicesKey[];
        }
        if (countryLocation === 'FR') {
            return ['bnp-paribas', 'credit-agricole', 'banque-populaire'] satisfies OnlineServicesKey[];
        }
        if (countryLocation === 'DE') {
            return ['deutsche-bank', 'dz-bank', 'kfw'] satisfies OnlineServicesKey[];
        }
        if (countryLocation === 'ES') {
            return ['santander', 'bbva', 'caixa-bank'] satisfies OnlineServicesKey[];
        }
        if (countryLocation === 'CH') {
            return ['ubs', 'raiffeisen', 'zurcher-kantonalbank'] satisfies OnlineServicesKey[];
        }
        // Default to US
        return ['bank-of-america', 'american-express', 'capital-one'] satisfies OnlineServicesKey[];
    } else if (category === 'social-media') {
        return ['facebook', 'instagram', 'tiktok'] satisfies OnlineServicesKey[];
    } else if (category === 'shopping') {
        return ['amazon', 'ebay', 'aliexpress'] satisfies OnlineServicesKey[];
    } else {
        throw new Error('Invalid category');
    }
};

const TabContent = memo(({ selectedCategory }: { selectedCategory: Category }) => {
    const { viewportWidth } = useActiveBreakpoint();
    const [sendMailOnboardingTelemetry] = useMailOnboardingTelemetry();
    const [countryLocation] = useMyCountry();
    const servicesKeys = getFinanceServicesByCountry({ category: selectedCategory, countryLocation }) || [];

    return (
        <ul key={selectedCategory} className="unstyled mx-0 my-4 divide-y divide-weak">
            {servicesKeys.map((key) => {
                const service = ONLINE_SERVICES[key];
                if (!service) {
                    return null;
                }

                return (
                    <li key={service.key} className="flex flex-row flex-nowrap items-center py-4">
                        <img
                            alt=""
                            src={service.img}
                            className="w-custom h-custom shrink-0 ml-1"
                            style={{
                                '--w-custom': '2rem',
                                '--h-custom': '2rem',
                            }}
                        />
                        <span className="flex-1 text-left px-2 text-ellipsis" title={service.name}>
                            {service.name}
                        </span>
                        <ButtonLike
                            as="a"
                            href={service.url}
                            rel="noopener noreferrer"
                            size={viewportWidth.xsmall ? 'medium' : 'small'}
                            target="_blank"
                            onClick={() => {
                                void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.change_login, {
                                    service: key,
                                });
                            }}
                            className="shrink-0"
                            icon={viewportWidth.xsmall}
                            pill={viewportWidth.xsmall}
                        >
                            {viewportWidth.xsmall ? (
                                <Icon name="arrow-out-square" alt={c('Action').t`Change email`} />
                            ) : (
                                c('Action').t`Change email`
                            )}
                        </ButtonLike>
                    </li>
                );
            })}
        </ul>
    );
});
TabContent.displayName = 'TabContent';

const UsersOnboardingReplaceAccountPlaceholder = ({ className }: { className?: string }) => {
    const [addresses] = useAddresses();
    const [selectedCategory, setSelectedCategory] = useState<Category>('finance');
    const sortedAddresses = sortAddresses(addresses || []);
    const updateMailAddressModal = useModalStateObject();
    const { createNotification } = useNotifications();
    const { viewportWidth } = useActiveBreakpoint();
    const { changeChecklistDisplay, canDisplayChecklist, markItemsAsDone } = useGetStartedChecklist();
    const [sendMailOnboardingTelemetry] = useMailOnboardingTelemetry();

    if (!canDisplayChecklist) {
        return null;
    }

    const handleChangeChecklistDisplay = () => {
        changeChecklistDisplay(CHECKLIST_DISPLAY_TYPE.REDUCED);
        markItemsAsDone('AccountLogin');
        void sendMailOnboardingTelemetry(TelemetryMailOnboardingEvents.finish_change_login, {});
    };

    const learnMoreLink = (
        <Button
            key="learn-more-link-change-addresses"
            shape="underline"
            color="norm"
            className="p-0 inline-block"
            onClick={() => updateMailAddressModal.openModal(true)}
        >{c('Link').t`Learn more`}</Button>
    );

    const categories: { id: Category; name: string }[] = [
        { id: 'finance', name: c('Onboarding List Placeholder').t`Finance` },
        { id: 'social-media', name: c('Onboarding List Placeholder').t`Social media` },
        { id: 'shopping', name: c('Onboarding List Placeholder').t`Shopping` },
    ];

    const defaultEmailAddress: string | undefined = sortedAddresses?.[0]?.Email;

    return (
        <>
            <div className={clsx('m-auto max-w-custom py-6', className)} style={{ '--max-w-custom': '35rem' }}>
                <div className="text-center mb-6 mx-4">
                    <h1 className="text-4xl text-bold mb-3">{c('Onboarding List Placeholder')
                        .t`Privacy for all your online accounts`}</h1>
                    <p className="text-weak mt-0">
                        {c('Onboarding List Placeholder')
                            .jt`Use your ${MAIL_APP_NAME} address to sign in to online services to avoid being tracked and profiled. Change your email for popular services now. ${learnMoreLink}`}
                    </p>
                    {!!defaultEmailAddress && (
                        <Tooltip title={c('Action').t`Click to copy ${defaultEmailAddress} to clipboard`}>
                            <Button
                                color="weak"
                                shape="outline"
                                size="small"
                                className="bg-transparent inline-flex items-center flex-nowrap"
                                onClick={() => {
                                    textToClipboard(defaultEmailAddress);
                                    createNotification({
                                        text: c('Info').t`Email copied to clipboard`,
                                    });
                                }}
                            >
                                {defaultEmailAddress}
                                <Icon className="ml-4" name="squares" />
                            </Button>
                        </Tooltip>
                    )}
                </div>
                <div
                    className={clsx([
                        'bg-norm border-weak pt-4 px-3 sm:px-4 md:px-8 mx-0 sm:mx-4 text-center',
                        viewportWidth.xsmall ? 'border-top border-bottom' : 'border rounded-xl',
                    ])}
                >
                    <Pills
                        size={viewportWidth.xsmall ? 'small' : 'medium'}
                        categories={categories}
                        selectedID={selectedCategory}
                        onClick={setSelectedCategory}
                    />
                    <TabContent selectedCategory={selectedCategory} />
                </div>
                <div className="text-center mb-4 mx-4">
                    <Button shape="underline" className="mt-4 color-weak" onClick={handleChangeChecklistDisplay}>{c(
                        'Onboarding List Placeholder'
                    ).t`I have moved my logins to ${BRAND_NAME}`}</Button>
                </div>
            </div>
            {updateMailAddressModal.render && <UpdateMailAddressModal {...updateMailAddressModal.modalProps} />}
        </>
    );
};

export default UsersOnboardingReplaceAccountPlaceholder;

import { c } from 'ttag';

